$g=$base;$g['stage']='partida';MatchExperience::begin($g);Evolution::gain($g,'passe',10);Progression::distribute($g,20,'match:ui-fixture');MatchExperience::finish($g);$match=$g['matches'][Game::currentIndex($g)];ok(isset($match['experience']['development_raw_xp']),'Raw XP in new report');$saved=$g;ob_start();MatchExperience::render($match);$html=ob_get_clean();ok(str_contains($html,'XP bruto de atividades')&&str_contains($html,'XP aplicados ao desenvolvimento'),'Explain conversion');ok($g===$saved,'UI never grants XP');
